class ScenarioDuration(object):
    """Class for scenario duration methods."""

    def __init__(self, executor):
        self.executor = executor
        self.get_status = self.executor.get_status

    def get_current_scenario_duration(self):
        """Keyword for getting duration of current scenario.

        :return: If scenario is running duration of the scenario otherwise None
        """
        status_qued = self.get_status()['queue']
        if status_qued.get('0'):
            return status_qued['0']['duration']

    def get_last_scenario_duration(self):
        """Keyword for getting last scenario duration.

        :return: Last scenario duration. If last scenario was with error or doesn't exist returns None
        """
        status_history = self.get_status(options="history 2")['history']
        executes = [(int(key), status_history[key]) for key in status_history]
        executes.sort(reverse=True)
        for number_key, execute_status in executes:
            if execute_status['finished'] == 'ERROR':
                return None
            elif execute_status['finished'] != 'IN_PROGRESS':
                return execute_status['duration']
